import {createMotionController} from '../shared/motion/motion-primitives.mjs';

// M18 consumes M00. No commands, router, timers, scroll interception or renderer.
export function mountAttachmentMotion({root,requested='auto',active=()=>true,media}){
 let controller=null,disposed=false,observer=null,pendingPage=null;
 const errors=new Map(),checks=new Map();
 const usable=()=>!disposed&&active()&&!root.closest('[inert]')&&!root.ownerDocument.hidden&&!root.closest('.hn-screen')?.querySelector('.app-modal-host,.p03-host:not([hidden])');
 const mark=(node,name)=>{if(node)node.dataset.motionPrimitive=name;return node;};
 function stop(){controller?.cancel();pendingPage=null;for(const n of root.querySelectorAll('.p18-progress-fill,.p18-slot'))for(const a of n.getAnimations?.()||[])a.finish();}
 function attachmentVisibility(){root.dataset.attachmentMotionHidden=String(root.ownerDocument.hidden);if(!usable())stop();}
 function release(){if(!controller)return;stop();observer?.disconnect();observer=null;root.ownerDocument.removeEventListener('visibilitychange',attachmentVisibility);controller.dispose();controller=null;delete root.dataset.attachmentMotionHidden;}
 return {
  activate(){if(disposed||controller)return;controller=createMotionController({element:root,requested,...(media?{media}:{})});root.ownerDocument.addEventListener('visibilitychange',attachmentVisibility);observer=new MutationObserver(()=>{if(!usable())stop();});observer.observe(root,{attributes:true,attributeFilter:['inert','hidden']});attachmentVisibility();},
  setMode(value){requested=value;stop();controller?.setMode(value);},
  beforeRender:stop,
  row(node){if(usable())controller?.rowFeedback(mark(node,'AttachmentRow'));},
  pageRequested(key){controller?.cancel();pendingPage=key;},
  pageReady(node,key){if(pendingPage!==key)return;pendingPage=null;if(usable())controller?.noticeFeedback(mark(node,'ViewerShell'));},
  validation(node,key,message,{seed=false}={}){const previous=errors.get(key)||'';errors.set(key,message);if(!seed&&message&&previous!==message&&usable())controller?.noticeFeedback(mark(node,'HandoffFormFeedback'));},
  check(node,key,value,{seed=false}={}){const previous=checks.get(key);checks.set(key,value);if(!seed&&previous!==value&&usable())controller?.noticeFeedback(mark(node,'HandoffCheck'));},
  cancel:stop,
  hide:release,
  dispose(){if(disposed)return;release();disposed=true;errors.clear();checks.clear();},
 };
}

@import url('./motion.css');
/* P18: B18 structure adapted to the user-locked 494x950 shell. Footer unchanged. */
#home-app .hn-screen.p18-screen{height:950px;min-height:950px;overflow:hidden;background:#f1f8fa}
#home-app .hn-attachments{display:flex;flex:1;min-height:0;overflow:hidden}
#home-app .p18-focus-screen>.hn-nav{display:none}
.p18-app{display:flex;flex-direction:column;flex:1;min-width:0;min-height:0;font:17px/1.5 Arial,sans-serif;color:#12384e;background:#f1f8fa}
.p18-app *{box-sizing:border-box}
.p18-app button,.p18-app input,.p18-app textarea{font:inherit}
.p18-icon{width:24px;height:24px;stroke:currentColor;stroke-width:1.8;fill:none;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0;vertical-align:middle}
.p18-app button{cursor:pointer;transition:background-color .15s;touch-action:manipulation}
.p18-app button:focus-visible,.p18-app input:focus-visible,.p18-app textarea:focus-visible{outline:3px solid #159abc;outline-offset:3px}
.p18-app button:disabled{cursor:default;opacity:.45}
.p18-app button:active:not(:disabled){filter:brightness(.94)}
.p18-header{display:flex;align-items:center;gap:10px;flex-shrink:0;height:76px;padding:12px 16px;color:white;background:linear-gradient(110deg,#073b52,#006c92)}
.p18-header h1{font-size:23px;line-height:1.25;margin:0;min-width:0;overflow-wrap:anywhere}
.p18-icon-button{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:44px;height:44px;border:0;border-radius:10px;background:transparent;color:inherit}
.p18-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:18px 20px 34px;display:flex;flex-direction:column;gap:14px;scrollbar-width:thin}
.p18-scroll>*{flex-shrink:0}
.p18-card{background:#fff;border:1px solid #e1edf2;border-radius:12px;padding:16px;min-width:0}
.p18-card h2{font-size:18px;line-height:1.4;margin:0 0 12px;font-weight:700;color:#12384e}
.p18-card p{margin:0;overflow-wrap:anywhere}
.p18-context{display:flex;align-items:center;gap:14px}
.p18-context>div{min-width:0;flex:1}
.p18-context strong{display:block;font-size:19px}
.p18-context small,.p18-file-copy small{display:block;color:#527186;font-size:14px;line-height:1.5;margin-top:3px}
.p18-context p{font-size:16px;color:#527186}
.p18-file-list{display:flex;flex-direction:column;gap:10px}
.p18-file{display:flex;gap:12px;padding:12px 8px 12px 12px;border:1px solid #e0ebf0;border-radius:10px;align-items:flex-start;background:#fcfefe;min-width:0}
.p18-file-copy{flex:1;min-width:0;overflow-wrap:anywhere}
.p18-file-copy strong{font-size:16px;display:block}
.p18-file-tile{width:54px;height:62px;border-radius:10px;background:#fff0f0;color:#c83341;display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0}
.p18-file-tile small{font-size:10px;line-height:15px;font-weight:bold}
.p18-file-tile .p18-icon{width:30px;height:32px}
.p18-thumb{width:54px;height:62px;object-fit:contain;background:#f4f7f8;border-radius:9px;flex-shrink:0}
