.p18-progress progress::-webkit-progress-value{background:#0094c4;border-radius:8px}
.p18-hint{display:flex;gap:12px;padding:14px;margin-top:16px;background:#eaf6fb;color:#32617b;border-radius:10px}
.p18-hint p{font-size:14px;line-height:1.6}
