.p18-hint strong{font-size:16px;color:#12384e}
.p18-footer{flex-shrink:0;padding:14px 20px 20px;display:flex;flex-direction:column;gap:12px;background:#f1f8fa}
.p18-primary{border:0;border-radius:9px;background:#007ca4;color:#fff;font-weight:700!important;min-height:56px;width:100%;padding:12px 15px}
.p18-download{display:flex;gap:10px;align-items:center}
.p18-download>.p18-icon-button{border:1px solid #d4e5ef;background:white;height:56px;width:52px}
.p18-primary>.p18-icon{margin-right:9px}
.p18-pager{display:flex;justify-content:center;align-items:center;gap:10px}
