.p18-paper [hidden]{display:none}
.p18-paper>[role=status]{padding:12px;font-size:16px}
.p18-paper>[role=status]:empty{display:none}
.p18-pdf-text{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.p18-pdf-text:focus{position:relative;width:auto;height:auto;clip-path:none;white-space:pre-wrap;font-size:15px;line-height:1.6}
.p18-kv{margin:0;display:flex;flex-direction:column;gap:7px}
.p18-kv>div{display:grid;grid-template-columns:145px minmax(0,1fr);gap:12px}
.p18-kv dt{color:#527186;font-size:15px}
.p18-kv dd{margin:0;overflow-wrap:anywhere;font-size:16px}
.p18-badge{display:inline-block;padding:3px 9px;background:#fff4dc;color:#87541e;border-radius:7px;font-size:14px}
.p18-label{margin:13px 0 5px!important;color:#527186;font-size:15px}
.p18-parts{border-collapse:collapse;width:100%;table-layout:fixed;font-size:16px}
.p18-parts th{text-align:left;color:#527186;background:#f2f8fb;font-size:14px;font-weight:400}
.p18-parts td,.p18-parts th{padding:9px;border-bottom:1px solid #e4edf1;overflow-wrap:anywhere}
.p18-parts th:last-child,.p18-parts td:last-child{width:50px;text-align:center}
.p18-parts small{display:block;font-size:13px;color:#527186}
#p18-handoff{display:flex;flex-direction:column;gap:14px}
.p18-check{display:flex;gap:11px;align-items:flex-start;cursor:pointer}
.p18-check input{width:23px;height:23px;accent-color:#007ea5;flex-shrink:0;margin:3px 0}
.p18-check strong{font-size:16px;display:block}
.p18-check small{color:#527186;font-size:14px;display:block;margin-top:6px}
.p18-field{display:block;font-size:16px;margin-top:14px}
.p18-field input,.p18-field textarea{display:block;width:100%;height:48px;border:1px solid #ccdfe8;border-radius:8px;padding:10px 12px;color:#12384e;margin-top:6px;background:white;min-width:0}
.p18-field textarea{height:80px;resize:none;line-height:1.5}
.p18-field small{font-size:13px;color:#527186}
.p18-field>small:last-child{display:block;text-align:right;margin-top:4px}
.p18-field input[aria-invalid=true],.p18-field textarea[aria-invalid=true]{border-color:#b43136}
.p18-error{color:#b43136!important;font-size:14px;line-height:1.5}
.p18-app em{font-style:normal;color:#b43136}
.p18-policy{font-size:14px;line-height:1.6;color:#527186;margin:0 4px}
.p18-locked{margin:0;display:flex;flex-direction:column;gap:7px}
