.p18-locked dt{width:115px;color:#527186;font-size:15px}
.p18-locked dd{flex:1;margin:0;font-weight:700;overflow-wrap:anywhere}
.p18-locked .p18-icon{width:19px;height:19px;color:#527186}
.p18-slots{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}
