.p18-slot[data-tone=empty]{background:#eef3f7;border-color:#d3e0e9}
.p18-slot[aria-pressed=true]{background:#eaf8ff;border:2px solid #0087b0;box-shadow:inset 0 0 0 1px #0087b0;color:#005c7d}
.p18-legend{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;margin-top:12px;color:#527186}
.p18-legend span:first-child{color:#007caa}
.p18-unavailable{display:flex;flex-direction:column;gap:12px;align-items:center;text-align:center;padding:12px 8px;color:#527186}
.p18-unavailable p{font-size:15px}
.p18-sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.p18-tools{margin-top:18px;border-top:1px solid #dce9ef;padding-top:12px}
