.p18-thumbnail-link{padding:0;background:transparent;border:0;border-radius:10px;flex-shrink:0;min-width:54px;min-height:62px}
.p18-file-name{display:block;text-align:left;width:100%;min-height:44px;border:0;background:transparent;color:#12384e;padding:0;overflow-wrap:anywhere}
