.p18-case-summary>p{font-weight:700;font-size:17px}
.p18-case-summary>small{display:block;margin-top:3px;color:#527186}
.p18-repair-details>summary,.p18-location-details>summary{cursor:pointer;min-height:44px;font-weight:700;line-height:1.5;overflow-wrap:anywhere}
.p18-repair-details>summary span{display:block;font-size:14px;font-weight:400;color:#527186;margin-left:18px}
.p18-repair-details h2{margin-top:18px}
.p18-location-details .p18-locked{margin-top:12px}
.p18-handoff-footer{gap:8px;padding-top:10px}
