.p18-view-controls{display:flex;align-items:center;gap:6px;min-width:0;flex-shrink:0}
.p18-view-controls button{width:44px;height:44px;border:1px solid #ccdfe8;background:white;border-radius:9px;color:#006887;font-size:24px;flex-shrink:0}
.p18-view-controls output{font-size:14px;text-align:center;min-width:42px;color:#527186}
.p18-fit-label{flex:1;min-width:0}
