.p18-app[data-panel="P18.S02"] .p18-paper canvas,.p18-app[data-panel="P18.S02"] .p18-paper img{width:var(--p18-page-width,100%);height:var(--p18-page-height,auto);max-width:none}
.p18-view-controls [hidden],.p18-next-step [hidden]{display:none}
/* r03 audit: stable guidance, explicit text reader and persistent control focus. */
.p18-next-step{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;min-height:44px;align-items:center}
.p18-next-step>span{line-height:21px}
