#home-app .p16-stale[data-data-state=refreshing] p{color:var(--p12-muted)}
#home-app .p16-searching{display:flex;align-items:center;justify-content:center;gap:14px;padding:40px 16px;color:var(--p12-muted);font-size:18px}
#home-app .p12-list-controls [data-p12=scan][aria-disabled=true]{opacity:.55;cursor:not-allowed}
#home-app .p16-scan-help{min-height:21px;font-size:15px;color:var(--p12-muted);margin:0 0 12px;line-height:1.4}

#home-app .p16-chips button:only-child{grid-column:1/-1}

/* r03: keep long search context readable without burying recovery actions. */
#home-app .p16-description[data-preview-key]{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}
#home-app .p16-query-more{margin-top:8px;min-height:36px;padding:6px 10px}
#home-app .p16-query-more[hidden]{display:none}
#home-app .p16-state .p16-query-more {min-height:44px;}

/* M16: only a pending owner read can drive the existing indicator. */
#home-app .p16-spinner[data-read-pending=true]{animation:p16-spin .9s linear infinite}
@media(prefers-reduced-motion:reduce){#home-app .p16-spinner[data-read-pending=true]{animation:none}}

