export function renderHistoryDetail(r,tab,icon,{statuses=DATA.statuses,related=true,documentLabel='Chứng từ liên quan',showDocumentHint=true,canOpenDocument=false,canOpenAttachments=false}={}){
 const status={...detailStatus(r.status),label:statuses[r.status]||'Chưa có dữ liệu'},events=r.events||[],files=r.attachments||[],latest=events.at(-1);
 const glyph={inbound:'down',outbound:'up',warranty:'tool',nfc:'nfc',documents:'document'};
