@font-face{font-family:HN-P22;src:url('../warranty-components/fonts/public-sans-2090ae7a.woff2') format('woff2');font-weight:100 900;unicode-range:U+0102-0103,U+0110-0111,U+0128-0129,U+0168-0169,U+01A0-01A1,U+01AF-01B0,U+0300-0301,U+0303-0304,U+0308-0309,U+0323,U+0329,U+1EA0-1EF9,U+20AB}
@font-face{font-family:HN-P22;src:url('../warranty-components/fonts/public-sans-f631476b.woff2') format('woff2');font-weight:100 900}
#home-app .hn-screen.p22-screen{height:950px;min-height:950px;overflow:hidden;background:#f3f9fb}
#home-app .p22-screen>.hn-nav{display:none}
#home-app .hn-nfc-audit{flex:1;min-height:0;min-width:0;display:flex;overflow:hidden}
.p22-app{display:flex;flex-direction:column;flex:1;min-height:0;min-width:0;font:16px/1.5 HN-P22,Arial,sans-serif;color:#12384e;background:#f3f9fb}
.p22-app *{box-sizing:border-box}
.p22-app button,.p22-app input{font:inherit}
.p22-app button{cursor:pointer;min-height:44px;touch-action:manipulation}
.p22-app button:focus-visible,.p22-app input:focus-visible{outline:3px solid #008cff;outline-offset:-3px}
.p22-app .p08-header{gap:12px}
.p22-app .p08-header button{width:44px;height:44px;flex-shrink:0}
#home-app .p22-app h1{font-size:26px;line-height:1.25}
.p22-scroll{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:20px 20px 24px;scrollbar-width:none;background:#f3f9fb;border-radius:24px 24px 0 0;margin-top:-12px}
.p22-app h2{font-size:22px;line-height:1.4;margin:0}
.p22-intro{font-size:14px;color:#527186;margin:0 0 16px!important}
.p22-controls .p08-tabs{margin-bottom:12px}
.p22-dock{flex-shrink:0;background:#f3f9fb;border-radius:24px 24px 0 0;margin-top:-12px;padding:20px 20px 0}
.p22-scroll.p22-list-scroll{margin-top:0;border-radius:0;padding-top:0}
.p22-controls .p08-tabs button{font-size:14px;white-space:normal}
