import {newFilters,textValue} from './warranty-session-model.mjs';
import {validQueryDate} from '../shared/query-date-policy.mjs';
export const hasHistoryFilters=f=>f.type!=='all'||f.status!=='all'||!!f.from||!!f.to;
export const clearHistoryConditions=f=>({...newFilters(),q:f.q});
export const acceptedLabel=r=>r.type==='Tra cứu'?'Lượt tra cứu hợp lệ':'Mã hợp lệ';
export function sessionNotice(r){
 if(r.type==='Tra cứu')return 'Phiên tra cứu không tạo phiếu kho hoặc thay đổi tồn.';
 if(r.type==='Nhập kho')return r.status==='Chờ xử lý trên Web'?'Phiếu đã gửi, chưa ghi sổ; chưa làm thay đổi tồn.':'Kết quả gửi phiếu chưa xác minh. Không suy trạng thái ghi sổ hoặc tồn kho từ việc kết thúc phiên.';
 return r.status==='Đã xuất'?'Kết quả xuất dựa trên nguồn xác nhận; kết thúc phiên không tự đồng nghĩa Đã xuất.':'Kết quả xuất chưa xác minh. Không suy Đã xuất hoặc số lượng đã xuất từ việc kết thúc phiên.';
}
export function latestWarrantyEvent(events){
 if(!events.length||events.some(e=>!validQueryDate(e.day)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.time)))return null;
 const ordered=events.slice().sort((a,b)=>b.day.localeCompare(a.day)||b.time.localeCompare(a.time));
 // Equal timestamps do not establish which event is the newest.
 return ordered.length>1&&ordered[0].day===ordered[1].day&&ordered[0].time===ordered[1].time?null:ordered[0].id;
}
export function sessionLinks(row,cases,receipts,warehouseId){
 if(!row||warehouseId!=='fixture-hoa-nam'||row.warehouseId!==warehouseId||row.type!=='Xuất linh kiện')return {};
 const c=cases.find(c=>c.id===row.caseId);if(!c)return {};
 const receipt=row.status==='Đã xuất'&&textValue(row.linkedReceiptId)&&receipts.find(r=>r.id===row.linkedReceiptId&&r.caseId===c.id&&r.status==='POSTED'&&r.warehouse==='Kho Hoa Nam');
 return {caseId:c.id,receiptId:receipt?receipt.id:null};
}

// B23-only opt-in fixture. PQ-0001 here is NOT the legacy B08 session.
export function sessionFixture(warehouseId,mode='unavailable'){
 if(mode==='unavailable')return {available:false};
 if(mode==='error')throw Error('PREVIEW_READ_ERROR');
 const event=(sessionId,n,code,time,quantity)=>({id:'B23-'+sessionId+'-E'+n,sessionId,code,time,quantity,result:'accepted'});
 const base={confirmed:true,warehouseId,warehouse:'Kho Hoa Nam',actor:'Minh Anh',day:'2026-09-10',sessionStatus:'Đã kết thúc',rejected:0,duplicate:0};
 const items=[
  {...base,id:'PQ-0003',type:'Xuất linh kiện',time:'14:30 – 14:45',result:'POSTED',doc:'XLK-0002',caseId:'BH-001',linkedReceiptId:'XLK-0002',accepted:2,quantity:3,events:[event('PQ-0003',1,'LK0001-HN001','14:31',1),event('PQ-0003',2,'BOX-LK-0002-01','14:33',2)]},
  {...base,id:'PQ-0002',type:'Nhập kho',time:'11:10 – 11:25',result:'RECORDED',doc:'PN-0005',accepted:12,quantity:null,events:null},
  {...base,id:'PQ-0001',type:'Tra cứu',time:'09:00 – 09:08',result:'ENDED',doc:null,accepted:5,quantity:null,events:null}
 ];
 if(mode==='long')for(const r of items){r.actor='Minh Anh — Tiếng Việt <>& 🌸\n'+('Tên người thao tác dài '.repeat(150));if(r.events)r.events[0].code='MÃ<>&🌸'+('ABC'.repeat(120));}
 if(mode==='missing'){items[0].accepted=null;items[0].rejected=null;items[0].quantity=null;items[0].duplicate=null;items[0].result=null;}
 return {available:true,confirmed:true,complete:true,items:mode==='empty'?[]:items};
}

// Read presentation only. This is not a backend schema or permission proposal.
import {sessionGuard} from '../home/home-flow.mjs';
import {readWarrantyCases} from '../shared/warranty-cases.mjs';
import {validQueryDate} from '../shared/query-date-policy.mjs';
export const SESSION_TYPES=['Nhập kho','Xuất linh kiện','Tra cứu'];
export const historyScope=s=>!sessionGuard(s)&&s.session.actor?.id&&s.session.warehouse?.id?JSON.stringify([s.session.actor.id,s.session.warehouse.id]):'';
export const newFilters=()=>({q:'',type:'all',status:'all',from:'',to:'',sort:'desc'});
export const textValue=v=>typeof v==='string'&&v.trim()?v:null;
export const countValue=v=>Number.isSafeInteger(v)&&v>=0?v:null;
export const findExact=(rows,id)=>rows.find(r=>r.id===id)||null;
export function warrantyRows(){return readWarrantyCases();}
export function caseEvents(row){const seen=new Set();return (Array.isArray(row?.events)?row.events:[]).filter(e=>textValue(e?.id)&&!seen.has(e.id)&&seen.add(e.id)).slice().reverse();}
const fold=s=>String(s??'').normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/đ/gi,'d').toLowerCase();
export function selectRows(rows,f,kind){return rows.filter(r=>(f.type==='all'||(kind==='warranty'?r.status:r.type)===f.type)&&(f.status==='all'||r.status===f.status)&&(!f.from||(validQueryDate(r.day)&&r.day>=f.from))&&(!f.to||(validQueryDate(r.day)&&r.day<=f.to))&&fold(kind==='warranty'?[r.id,r.serial].join(' '):[r.id,r.doc].join(' ')).includes(fold(f.q.trim()))).slice().sort((a,b)=>String(b.day||'').localeCompare(String(a.day||''))||String(b.time||'').localeCompare(String(a.time||''))||b.id.localeCompare(a.id));}
export function normalizeSessions(result,warehouseId){
 if(result?.available!==true||result?.confirmed!==true||!Array.isArray(result.items))return {kind:'unavailable',items:[]};
 const items=[],ids=new Set();
 for(const row of result.items){
  if(!textValue(row?.id)||row.warehouseId!==warehouseId||!SESSION_TYPES.includes(row.type)||row.confirmed!==true)return {kind:'unavailable',items:[]};
  if(ids.has(row.id))continue;ids.add(row.id);
  const r={id:row.id,type:row.type,warehouseId};
  for(const key of ['day','time','actor','warehouse','doc','caseId','linkedReceiptId','sessionStatus'])r[key]=textValue(row[key]);
  for(const key of ['accepted','rejected','duplicate','quantity'])r[key]=countValue(row[key]);
  // Completion is not proof of posting; only confirmed operation result is used.
  r.status=row.type==='Xuất linh kiện'&&row.result==='POSTED'&&r.doc?'Đã xuất':row.type==='Nhập kho'&&row.result==='RECORDED'&&r.doc?'Chờ xử lý trên Web':row.type==='Tra cứu'&&row.result==='ENDED'?'Đã kết thúc':'Chưa xác minh kết quả';
  if(r.type==='Tra cứu'){r.doc=null;r.quantity=null;}
  if(r.type!=='Xuất linh kiện'||r.status!=='Đã xuất')r.quantity=null;
  const events=[],eventIds=new Set();
  for(const e of Array.isArray(row.events)?row.events:[]){
   if(!textValue(e?.id)||e.sessionId!==r.id||!['accepted','rejected','duplicate'].includes(e.result))return {kind:'unavailable',items:[]};
   if(eventIds.has(e.id))continue;eventIds.add(e.id);
   events.push({id:e.id,sessionId:e.sessionId,code:textValue(e.code),time:textValue(e.time),result:e.result,quantity:countValue(e.quantity)});
  }
  r.events=events;r.eventsKnown=Array.isArray(row.events);items.push(r);
 }
 return {kind:'ready',items,complete:result.complete===true};
}

import {createMotionController} from '../shared/motion/motion-primitives.mjs';

// M23 consumes M00. Native scroll, route, overlay and business data remain with their owners.
export function mountWarrantySessionMotion({root,requested='auto',active=()=>true,media}){
 let controller=null,disposed=false,filterKey=null;
 const available=()=>!disposed&&active()&&!root.closest('[inert],[hidden]');
 function press(e){
  if(!available()||e.type==='keydown'&&(e.repeat||e.isComposing||!['Enter',' '].includes(e.key)))return;
  const node=e.target.closest?.('.p23-app button:not([data-p23-type])');
  if(!node||!root.contains(node)||node.disabled||node.getAttribute('aria-disabled')==='true'||node.matches('[data-hn-read-trigger]'))return;
  node.dataset.motionPrimitive=root.querySelector('.p23-app')?.dataset.panel?.match(/S0[12]$/)?'WarrantyHistorySelection':'ScanSessionSelection';
  controller?.pressFeedback(node);
 }
 function release(){controller?.dispose();controller=null;root.removeEventListener('pointerdown',press);root.removeEventListener('keydown',press);filterKey=null;}
 return {
  activate(){if(disposed||controller)return;controller=createMotionController({element:root,requested,...(media?{media}:{})});root.addEventListener('pointerdown',press);root.addEventListener('keydown',press);},
  setMode(value){requested=value;controller?.setMode(value);},
  seed(key){filterKey=key;},
  filter(key,node,family){
   const changed=filterKey!==null&&filterKey!==key;filterKey=key;
   if(!changed||!available())return;controller?.cancel();
   if(node){node.dataset.motionPrimitive=family==='warranty'?'WarrantyHistoryFilter':'ScanSessionFilter';controller?.noticeFeedback(node);}
  },
  cancel(){controller?.cancel();},
  hide:release,
  dispose(){disposed=true;release();},
 };
}

