import {createMotionController} from '../shared/motion/motion-primitives.mjs';

// One presentation owner for the live route. No navigation, store, scroll or exit clone.
export function mountShellMotion({screen,requested='auto',media}) {
  const motion=createMotionController({element:screen,requested,...(media?{media}:{})});
  let routeKey=null,selectedTab=null,disposed=false;
  function press(event) {
    if(event.type==='keydown'&&(event.repeat||event.isComposing||!['Enter',' '].includes(event.key)))return;
    const hub=!!screen.querySelector('.hn-hub iframe');
    const button=event.target.closest?.(hub?'#hn-home button,.hn-nav button':'#hn-home button');
    if(!button||!screen.contains(button)||button.closest('[hidden], [inert], dialog')||button.disabled||button.getAttribute('aria-disabled')==='true')return;
    if(hub&&button.closest('.hn-nav'))button.dataset.motionPrimitive='HistoryHubNav';
    motion.pressFeedback(button);
  }
  screen.addEventListener('pointerdown',press);
  screen.addEventListener('keydown',press);
  return {
    get mode(){return motion.mode;},get activeCount(){return motion.activeCount;},
    setMode:value=>motion.setMode(value),
    commit(key,content,selected,{securitySensitive=false}={}) {
      if(disposed)return;
      const changed=routeKey!==key,tabChanged=selectedTab!==selected;
      if(securitySensitive){motion.cancel();routeKey=key;selectedTab=selected;return;}
      // Same-module query/panel/Back repaint is not a new route entrance.
      if(changed){motion.cancel();motion.routeTransition(content);}
      if(tabChanged&&selectedTab)motion.noticeFeedback(selected);
      routeKey=key;selectedTab=selected;
    },
    cancel:()=>motion.cancel(),
    dispose(){if(disposed)return;disposed=true;screen.removeEventListener('pointerdown',press);screen.removeEventListener('keydown',press);motion.dispose();},
  };
}

import {sessionGuard} from './home-flow.mjs';
import {pendingStockRun} from '../shared/flow-guidance.mjs';
// Read-only owner snapshots. Never allocate a document or reconstruct a scan session.
export function pendingWork(auth, sources) {
  if(sessionGuard(auth))return [];
  return sources.flatMap(({operation,snapshot:s})=>{
    const d=pendingStockRun(operation,s,auth.session)?.document;
    if(!d?.documentId||!d.scanSessionId||d.version==null)return [];
    return [{operation,id:d.documentId,number:d.number,scanSessionId:d.scanSessionId,version:d.version,
      acceptedCount:s.accepted?.length||0,busy:s.busy===true,unknown:s.unknown===true,
      label:s.unknown?'Cần đối chiếu':s.busy?'Đang gửi phiếu':'Tiếp tục phiếu đang làm'}];
  });
}

import {initialFilters,selectDocuments,TYPES,STATUSES} from '../documents/document-model.mjs';
import {recentTimeLabel} from '../shared/recent-time.mjs';
export const HOME_RECENT_LIMIT = 3;
const validTime = row => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(row.day || '') || !/^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(row.time || '')) return false;
  const date = new Date(row.day + 'T00:00:00Z');
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === row.day;
};
// Select from the complete P12 source, not a separate Home dataset or a loaded page.
export function recentDocuments(rows,now=Date.now()) {
  const eligible = [...new Map(rows.filter(row => row.id && row.number && Object.hasOwn(TYPES,row.type) && validTime(row)).map(row => [row.id,row])).values()];
  return selectDocuments({...initialFilters(),sort:'desc'},eligible).slice(0,HOME_RECENT_LIMIT).map(row => ({
    id:row.id, number:row.number, type:row.type,
    icon:row.type==='inbound'?'down':row.type==='outbound'?'up':'tool',
    description:TYPES[row.type],
    datetime:`${row.day}T${row.time}${row.time.length===5?':00':''}+07:00`,
    time:recentTimeLabel(row.day,row.time,now),
    fullTime:row.day.split('-').reverse().join('/')+' '+row.time+' (UTC+7)',
    label:STATUSES[row.status] || 'Chưa xác minh',
    tone:['posted','returned'].includes(row.status)?'green':['waiting','warrantyWaiting','ready'].includes(row.status)?'amber':['processing','received','checking'].includes(row.status)?'blue':'neutral',
  }));
}

