import {createMotionController} from '../shared/motion/motion-primitives.mjs';
// P06 owns only result/selected-tab feedback. M02 owns route opacity.
export function mountLookupMotion({root,requested='auto',active=()=>true}){
 let controller=null,disposed=false;
 const label=(node,name)=>{if(node)node.dataset.motionPrimitive=name;return node;};
 return {
  activate(){if(!disposed&&!controller)controller=createMotionController({element:root,requested});},
  setMode(value){requested=value;controller?.setMode(value);},
  search(node){if(active())controller?.dataState(label(node,'SearchFeedback'));},
  tab(node){if(active())controller?.noticeFeedback(label(node,'TabFeedback'));},
  cancel(){controller?.cancel();},
  hide(){controller?.dispose();controller=null;},
  dispose(){disposed=true;controller?.dispose();controller=null;},
 };
}

// Read identity/cancellation belongs to the data layer, never to animation.
// Supports the current synchronous fixture and future promise-based read adapters.
export function createLookupReadOwner({onCommit=()=>{}}={}){
 const current=new Map(),cache=new Map();let disposed=false,sequence=0;
 const empty=()=>({items:[],totals:{}});
 function cancel(){for(const request of current.values())request.abort.abort();current.clear();sequence++;}
 function invalidate(){cancel();}
 function read(kind,key,load){
  if(disposed)return {...empty(),error:'Nguồn đọc đã đóng.'};
  if(current.get(kind)?.key===key)return current.get(kind).value;
  current.get(kind)?.abort.abort();
  const request={id:++sequence,key,abort:new AbortController(),value:{...(cache.get(key)||empty()),loading:true,stale:cache.has(key)}};
  current.set(kind,request);
  const accepted=()=>!disposed&&!request.abort.signal.aborted&&current.get(kind)===request;
  function settle(result,notify){
   if(!accepted())return;
   if(!result||!Array.isArray(result.items))result={error:'Phản hồi dữ liệu chưa hợp lệ.',items:[]};
   if(result.error)request.value={...(cache.get(key)||empty()),error:result.error,stale:cache.has(key),loading:false};
   else{request.value={...result,loading:false};cache.set(key,request.value);if(cache.size>32)cache.delete(cache.keys().next().value);}
   if(notify)onCommit(kind,key,request.value);
  }
  try{const result=load(request.abort.signal);if(result?.then)Promise.resolve(result).then(value=>settle(value,true),()=>settle({error:'Không tải được dữ liệu. Vui lòng thử lại.',items:[]},true));else settle(result,false);}
  catch{settle({error:'Không tải được dữ liệu. Vui lòng thử lại.',items:[]},false);}
  return request.value;
 }
 return {read,invalidate,cancel,dispose(){disposed=true;cancel();cache.clear();}};
}

import {sessionGuard} from '../home/home-flow.mjs';

const categories=new Set(['products','components']);
const validId=value=>typeof value==='string'&&value.length>0;

// Memory of IDs only. Labels, inventory and serials always come from a fresh read.
export function createRecentLookupItems({getState}) {
  let currentScope=null;
  const ids=new Map();
  function scope(){
    const state=getState(),session=state?.session;
    const key=!sessionGuard(state)&&validId(session.authSessionId)&&validId(session.actor?.id)&&validId(session.warehouse?.id)
      ?JSON.stringify([session.authSessionId,session.actor.id,session.warehouse.id]):null;
    if(key!==currentScope||key===null){ids.clear();currentScope=key;}
    return key?session:null;
  }
  return {
    remember(item){
      const session=scope();
      if(!session||!validId(item?.id)||!categories.has(item.category)||item.warehouseId!==session.warehouse.id)return false;
      ids.set(item.category,[item.id,...(ids.get(item.category)||[]).filter(id=>id!==item.id)].slice(0,3));return true;
    },
    items(category,source){
      const session=scope();
      if(!session||!categories.has(category)||source?.error||!Array.isArray(source?.items))return [];
      return (ids.get(category)||[]).map(id=>source.items.find(item=>item.id===id&&item.category===category&&item.warehouseId===session.warehouse.id)).filter(Boolean);
    },
    clear(){ids.clear();currentScope=null;},
  };
}

// Used by both ordinary product navigation and the NFC product picker. A cached
// row is never sufficient authority to open/select an item after a read failure.
export function resolveLookupSelection({adapter,scope,category,id}) {
  if(!scope||!validId(id)||!categories.has(category))return {kind:'blocked',message:'Chưa xác minh được phạm vi tra cứu.'};
  try {
    const source=adapter.search(scope,{category,query:''});
    if(source?.error||!Array.isArray(source?.items))return {kind:'unavailable',message:source?.error||'Chưa đọc được nguồn sản phẩm. Vui lòng thử tải lại.'};
    const listed=source.items.find(item=>item.id===id&&item.category===category&&item.warehouseId===scope.warehouseId);
    if(!listed)return {kind:'missing',message:'Sản phẩm không còn trong dữ liệu vừa tải hoặc chưa xác minh được quyền xem. Hãy tải lại danh sách.'};
    const item=adapter.item(scope,id);
    if(!item||item.id!==id||item.category!==category||item.warehouseId!==scope.warehouseId)return {kind:'missing',message:'Chưa xác minh được thông tin hiện tại của sản phẩm. Hãy tải lại danh sách.'};
    return {kind:'item',item};
  }catch{return {kind:'unavailable',message:'Chưa đọc được nguồn sản phẩm. Vui lòng thử tải lại.'};}
}

