 const copy=uid=>`<button class="p07-copy" data-p07="copy" data-uid="${esc(uid)}" aria-label="Sao chép mã thẻ ${esc(uid)}">${icon('copy')}<span class="p07-copy-note" role="status" aria-live="polite"></span></button>`;
