 function cards(){const data=listData();if(!listReady(data))return '<div class="p07-empty"><strong>Chưa tải được danh sách thẻ</strong><p role="status">Chưa xác minh thông tin hiện tại. Thử tải lại danh sách.</p><button data-p07="retry-list" class="p07-inline-action">Thử tải lại</button></div>';return data.items.length?data.items.map(t=>`<button class="p07-tag" data-p07-tag="${esc(t.id)}">${tile()}<span class="p07-tag-copy"><span class="p07-tag-top"><strong>${esc(t.label)}</strong>${chip(t.status)}</span><b>${esc(t.product?.name||'Chưa gắn sản phẩm')}</b><small>${t.product?`SN: ${esc(t.product.serial)} <span class="p07-divider">|</span> SKU: ${esc(t.product.sku)}`:`UID: ${esc(t.uid)}`}</small><small>${t.status==='unlinked'?'Tạo':'Cập nhật'}: ${esc(t.date)}</small></span>${icon('chevron')}</button>`).join(''):'<div class="p07-empty"><strong>Không tìm thấy thẻ</strong><p role="status">Thử tìm theo UID, mã sản phẩm, SKU hoặc serial.</p><button data-p07="clear-filters" class="p07-inline-action">Xóa tìm kiếm và bộ lọc</button></div>';}
 function list(){const s=flow.snapshot(),counts=listReady(listData())?listData().counts:{};return `<button class="p07-entry" data-p07="begin">${tile()}<span><strong>Quét hoặc liên kết thẻ NFC</strong><small>Đọc UID, liên kết với sản phẩm</small></span>${icon('chevron')}</button><div class="p07-search-row"><div class="p07-search-field">${icon('search')}<input id="p07-search" enterkeyhint="search" autocomplete="off" value="${esc(s.query)}" placeholder="Tìm UID, mã, SKU, serial..." aria-label="Tìm thẻ theo UID, sản phẩm, serial"><button data-p07="clear-query" class="p07-clear-query" aria-label="Xóa tìm kiếm" ${s.query?'':'hidden'}>${icon('close')}</button></div><button data-p07="filter" aria-label="Bộ lọc thẻ NFC">${icon('filter')}</button></div><div class="p07-tabs" role="tablist" aria-label="Trạng thái thẻ">${[['all','Tất cả'],['linked','Đã liên kết'],['unlinked','Chưa liên kết']].map(([v,l])=>`<button id="p07-tab-${v}" role="tab" aria-controls="p07-list" aria-selected="${s.tab===v}" tabindex="${s.tab===v?0:-1}" data-p07-tab="${v}">${l} (${counts[v]??'—'})</button>`).join('')}</div><div class="p07-list" id="p07-list" role="tabpanel" aria-labelledby="p07-tab-${s.tab}">${cards()}</div>`;}
 function read(){const s=flow.snapshot(),blocked=s.read&&!flow.canContinue();
  const unavailable=getState().session?.warehouse.active!==true?'Kho tạm dừng':adapter.capabilities().link!==true?'Không có quyền liên kết':adapter.capabilities().read!==true?'Không hỗ trợ NFC':s.dependency?.reason==='nfc-permission-denied'?'Chưa có quyền đọc':'';
  const stateLabel=s.listening?'Đang đọc…':s.busy?'Đang kiểm tra…':unavailable|| (blocked?'Chưa thể liên kết':s.read?'Đã đọc UID':s.dependency?.reason==='nfc-read-error'?'Chưa đọc được':'Sẵn sàng đọc');
