  dialog.innerHTML=`<h2 class="app-modal-heading" id="p07-detail-title"><button class="p07-dialog-back" data-p07="close-detail" aria-label="Quay lại màn trước">${icon('back')}</button><span>Thông tin thẻ ${esc(tag.label)}</span></h2><div class="app-modal-body" tabindex="0" role="region" aria-label="Chi tiết thẻ NFC"><dl>${row('Mã thẻ (UID)',esc(tag.uid),'',copy(tag.uid))}${row('Trạng thái',chip(tag.status))}${row('Sản phẩm',esc(tag.product?.name))}${row('SKU',esc(tag.product?.sku))}${row('Serial',esc(tag.product?.serial))}${row(tag.status==='unlinked'?'Ngày tạo':'Cập nhật',esc(tag.date))}</dl><p class="p07-hint">Thông tin hiện tại của thẻ. Chưa có nguồn dữ liệu lịch sử thao tác.</p></div><footer class="app-modal-footer"><button class="p07-secondary" data-p07="close-detail">Đóng</button></footer>`;
  detailTagId=id;detailTrigger=document.activeElement;detailRoute.begin();
  detailModal=openAppModal({motionMode:root.querySelector('[data-panel="P17.S03"]')?motionMode:null,screen,parent:root.querySelector('.p07-app'),dialog,tools,dismissOnBackdrop:false,initialFocus:'footer [data-p07="close-detail"]',onClose:()=>{detailModal=null;detailTagId=null;detailRoute.closed();}});
 }
 async function onClick(e){
  if(!active)return;const b=e.target.closest('button');if(!b||b.disabled||!root.contains(b))return;
  if(b.dataset.p07Tag){showDetail(b.dataset.p07Tag);return;}
  if(b.dataset.p07Tab){if(flow.snapshot().tab===b.dataset.p07Tab)return;listTop=0;flow.tab(b.dataset.p07Tab);root.querySelector(`[data-p07-tab="${b.dataset.p07Tab}"]`)?.focus({preventScroll:true});motion.selected(root.querySelector(`[data-p07-tab="${b.dataset.p07Tab}"]`));return;}
  const a=b.dataset.p07,s=flow.snapshot();
  if(a==='exception-detail'){const id=flow.snapshot().dependency?.tagId;if(id)showDetail(id);return;}
  if(a==='exception-cancel'){closeException();return;}
  if(a==='begin'||a==='new-link')beginNext();
  if(a==='back'){if(backPending||detailRoute.isClosing())return;if(s.panel===1){onHome();return;}const parent=s.panel===4?1:s.panel-1;if(history.state?.p07From===hashFor(parent)){backPending=true;history.back();}else if(flow.panel(parent))history.replaceState(null,'',hashFor(parent));}
  if(['product','change-product'].includes(a)&&!s.busy&&!s.unknown){pickerReturn={scroll:root.querySelector('.p07-scroll')?.scrollTop||0,action:a};onChooseProduct({itemId:s.itemId});}
