 if(s.records.some(r=>r.saveBlocked))return {key:'owner-pending',tone:'warning',title:'Còn phiếu linh kiện đang làm',message:'Tiếp tục đúng phiếu xuất linh kiện trước khi kết thúc ca. Lưu nháp linh kiện qua P21 chưa được tích hợp.',action:'continue-first'};
