 const review=document.createElement('section');review.className='p14-tools';review.hidden=true;
 review.innerHTML=`<details><summary>P14 · Kịch bản kiểm chứng</summary><p>PROTOTYPE r06 · B14. Chỉ mô phỏng trong bộ nhớ trang; không gửi yêu cầu thật. Kênh khôi phục, policy lưu nháp/kết thúc ca và aggregate backend còn chờ chốt. Không bàn giao quyền sở hữu nháp. Nháp của luồng đăng xuất P14 được giữ theo tài khoản/kho trong bộ nhớ trang và phục hồi vào owner khi đăng nhập lại. Không phải lưu bền vững WMS; reload/reset đặt lại fixture.</p><p>KPI B14: 12 nhập + 6 xuất + 4 bảo hành + 3 NFC + 5 lượt xem chứng từ = 30 sự kiện tách biệt. Không tính từ danh sách client. Phiếu dở dùng cùng nguồn P04/P05/P03; số phiếu giữ đúng nguồn, không đổi thành PN-0001 chỉ để khớp ảnh.</p><label>Kết quả adapter <select data-p14-scenario><option value="ready">Xác nhận fixture</option><option value="error">Thất bại</option><option value="unknown">UNKNOWN chưa đối chiếu</option><option value="timeout-recorded">Timeout, nguồn đã ghi nhận</option><option value="blocked">Chưa có kết nối production</option></select></label></details>`;
 tools.append(review);
 const feedback=createActionFeedback({getScreen:()=>screen,tools,isActive:()=>active&&!disposed,key:'hnP14'+mode,motionMode});
 const recordsDialog=createRecordDialog({screen,tools,isActive:()=>active&&!disposed,onChoose:resumeRecord,motionMode});
 function remember(){const app=root.querySelector('.p14-app');if(!active||!app)return;const focus=document.activeElement,prior=contexts.get(panel)||{};let next={...prior,top:app.querySelector('.p14-scroll').scrollTop};
  if(root.contains(focus)&&focus.id==='p14-username')next={...next,field:focus.id,start:focus.selectionStart,end:focus.selectionEnd,direction:focus.selectionDirection,action:null,id:null};
  else if(root.contains(focus)&&focus.dataset.p14)next={...next,action:focus.dataset.p14,id:focus.dataset.document||null,field:null};
  contexts.set(panel,next);
 }
 function restore(focus){cancelRestoreFrames();const c=contexts.get(panel),app=root.querySelector('.p14-app'),scroll=app.querySelector('.p14-scroll'),token=++restoreEpoch;
  const valid=()=>active&&!disposed&&app.isConnected&&token===restoreEpoch;
  const applyScroll=()=>{if(valid()&&c)scroll.scrollTop=c.top;};applyScroll();
  const target=c?.field?app.querySelector('#p14-username'):c?.id?app.querySelector(`[data-document="${CSS.escape(c.id)}"]`):c?.action?app.querySelector(`[data-p14="${CSS.escape(c.action)}"]`):null;
  if(focus&&!screen.querySelector('.app-modal-host')){(target&&!target.disabled?target:app.querySelector('h1')).focus({preventScroll:true});if(target?.id==='p14-username'&&!target.disabled&&c.start!=null)target.setSelectionRange(c.start,c.end,c.direction);}
  // Reapply only scroll after reader measurement. Never steal focus after Tab,
  // and stop deferred restoration when the user scrolls/clicks or leaves.
  if(c)restoreFrame(()=>restoreFrame(applyScroll));
