/* Shared app-only scroll policy. Keep native wheel/touch/keyboard scrolling;
   suppress desktop scrollbar chrome and its layout gutter, never content. */
html:has(#app), html:has(#home-app), html:has(.phone) {
  scrollbar-width: none !important;
  scrollbar-gutter: auto !important;
}
#app, #app *, #home-app .hn-screen, #home-app .hn-screen *, .phone, .phone * {
  scrollbar-width: none !important;
  scrollbar-gutter: auto !important;
}
html:has(#app)::-webkit-scrollbar, html:has(#home-app)::-webkit-scrollbar,
html:has(.phone)::-webkit-scrollbar,
#app::-webkit-scrollbar, #app *::-webkit-scrollbar,
#home-app .hn-screen::-webkit-scrollbar, #home-app .hn-screen *::-webkit-scrollbar,
