import {createActionFeedback} from './action-feedback.mjs';

// Read-only presentation. Never reads input values, alters a source record,
// persists text, or shortens confirmation/warning content inside an overlay.
export const isTextTruncated = node => !!node && (node.scrollHeight > node.clientHeight + 1 || node.scrollWidth > node.clientWidth + 1);

export function mountReadableText({root,getScreen,getTools=()=>null,isActive=()=>!root.hidden,key='hnReadableText'}) {
  let disposed=false,frame=0,origin=null;
  const nodes=new Map(),triggers=new WeakMap();
  const resize=new ResizeObserver(()=>schedule());
  const active=()=>!disposed&&isActive();
  // Register navigation before module routers; lazy listeners can let a Back
  // repaint the caller before the temporary reader history entry is consumed.
  const feedback=createActionFeedback({getScreen,tools:getTools,isActive:()=>active()&&!!origin?.isConnected,key});
  function release(node,entry){resize.unobserve(node);entry.button.remove();node.classList.remove('hn-readable-excerpt');node.removeAttribute('data-hn-truncated');for(const key of ['--hn-readable-lines','--hn-readable-leading','--hn-readable-value-leading'])node.style.removeProperty(key);nodes.delete(node);}
  function eligible(node){return !node.matches('input,textarea,select,option,button,a') && !node.closest('dialog,.app-modal-host,.p03-dialog,[role=alert],[role=status],[role=alertdialog],[role=dialog],[data-hn-critical]') && (!node.closest('button,a') || node.dataset.hnReadOutside==='true'&&!!node.closest('[data-hn-readable-group]')) && !node.querySelector('input,textarea,select,button,a,img,svg');}
  function sync(){
    frame=0;if(disposed)return;
    if(origin&&(!origin.isConnected||!root.contains(origin)||!origin.hasAttribute('data-hn-readable')||!active())){feedback?.clear();origin=null;}
    for(const [node,entry] of nodes)if(!node.isConnected||!root.contains(node)||!node.hasAttribute('data-hn-readable')||!eligible(node))release(node,entry);
    if(!active())return;
    for(const node of root.querySelectorAll('[data-hn-readable]')){
      if(!eligible(node))continue;
      let entry=nodes.get(node);
      if(!entry){
        if(node.dataset.hnReadableKind==='value'){const original=getComputedStyle(node);node.style.setProperty('--hn-readable-value-leading',original.lineHeight==='normal'?'normal':String(parseFloat(original.lineHeight)/parseFloat(original.fontSize)));}
        const button=document.createElement('button');button.type='button';button.className='hn-read-more';button.dataset.hnReadTrigger='';button.hidden=true;button.textContent='Xem đầy đủ';button.setAttribute('aria-haspopup','dialog');
        if(node.closest('button,a'))node.closest('[data-hn-readable-group]').append(button);else node.after(button);node.classList.add('hn-readable-excerpt');
        entry={button};nodes.set(node,entry);triggers.set(button,node);resize.observe(node);
      }
      const lines=node.dataset.hnLines==='3'?3:2;
      node.style.setProperty('--hn-readable-lines',String(lines));
      const style=getComputedStyle(node),leading=parseFloat(style.lineHeight)||parseFloat(style.fontSize)*1.5;
      const height=`${leading}px`;if(node.style.getPropertyValue('--hn-readable-leading')!==height)node.style.setProperty('--hn-readable-leading',height);
      const clipped=isTextTruncated(node);if(entry.button.hidden===clipped)entry.button.hidden=!clipped;
      entry.button.setAttribute('aria-label','Xem đầy đủ '+(node.dataset.hnReadable||'nội dung').toLocaleLowerCase('vi'));
      node.dataset.hnTruncated=String(clipped);
    }
  }
  function schedule(){if(!disposed&&!frame)frame=requestAnimationFrame(sync);}
  const mutation=new MutationObserver(schedule);
  mutation.observe(root,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['hidden','data-hn-readable','data-hn-lines']});
  function onClick(event){
    const button=event.target.closest('[data-hn-read-trigger]');if(!button||!root.contains(button)||button.hidden||!active())return;
    const node=triggers.get(button);if(!node?.isConnected||!eligible(node))return;
    const screen=getScreen();if(!screen||screen.querySelector('.app-modal-host,dialog[open],.p03-host:not([hidden])'))return;
    event.preventDefault();event.stopImmediatePropagation();origin=node;
    feedback.show({title:node.dataset.hnReadable||'Nội dung đầy đủ',message:node.textContent,confirmLabel:'Đóng',className:'hn-readable-dialog'});
  }
  root.addEventListener('click',onClick,true);window.addEventListener('resize',schedule);schedule();
  return {refresh:schedule,dispose(){disposed=true;cancelAnimationFrame(frame);mutation.disconnect();resize.disconnect();feedback?.dispose();for(const [node,entry]of nodes){entry.button.remove();node.classList.remove('hn-readable-excerpt');node.removeAttribute('data-hn-truncated');node.style.removeProperty('--hn-readable-lines');node.style.removeProperty('--hn-readable-leading');node.style.removeProperty('--hn-readable-value-leading');}nodes.clear();root.removeEventListener('click',onClick,true);window.removeEventListener('resize',schedule);}};
}

const vietnamDay = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'});
export function recentTimeLabel(day,time,now=Date.now()) {
  const parts=Object.fromEntries(vietnamDay.formatToParts(new Date(now)).map(p=>[p.type,p.value]));
  const today=`${parts.year}-${parts.month}-${parts.day}`;
  const delta=(Date.parse(today+'T00:00:00Z')-Date.parse(day+'T00:00:00Z'))/86400000;
  const label=delta===0?'Hôm nay':delta===1?'Hôm qua':day.slice(0,4)===parts.year?day.slice(5).split('-').reverse().join('/'):day.split('-').reverse().join('/');
  return `${label} · ${time}`;
}

/* Only explicitly measured controls opt in. Original visual bounds stay intact. */
:where([data-hn-hit-ready]){position:relative;touch-action:manipulation}
[data-hn-hit-ready]::before{content:"";position:absolute;left:var(--hn-hit-left);top:var(--hn-hit-top);width:var(--hn-hit-width);height:var(--hn-hit-height);background:transparent;pointer-events:auto}

// Opt-in hit geometry for a uniformly scaled preview. Presentation only:
// no route, permission, input value, or locked navigation styling is changed.
export function mountScaledControls({screen,selector,isActive=()=>true,minPixels=44,layout=false}) {
  let frame=0,disposed=false;
  const nodes=new Set();
  const props=['--hn-hit-left','--hn-hit-top','--hn-hit-width','--hn-hit-height'];
  function clearHit(node){node.removeAttribute('data-hn-hit-ready');for(const key of props)node.style.removeProperty(key);}
  function release(node){clearHit(node);node.style.removeProperty('--hn-control-hit-min');if(layout){node.removeAttribute('data-hn-touch-layout');node.style.removeProperty('--hn-control-layout-min-height');node.style.removeProperty('--hn-control-layout-min-width');}resize.unobserve(node);nodes.delete(node);}
  function refresh(){
    frame=0;if(disposed)return;
    for(const node of nodes)if(!node.isConnected||!isActive()||!node.matches(selector))release(node);
    if(!isActive())return;
    const shell=screen.getBoundingClientRect(),scale=shell.width/screen.offsetWidth;
    if(!Number.isFinite(scale)||scale<=0)return;
    if(layout)screen.style.setProperty('--hn-priority-hit-min',`${minPixels/scale}px`);
    for(const node of screen.querySelectorAll(selector)){
      if(!nodes.has(node)){if(layout){const css=getComputedStyle(node);node.style.setProperty('--hn-control-layout-min-height',css.minHeight==='auto'?'0px':css.minHeight);node.style.setProperty('--hn-control-layout-min-width',css.minWidth==='auto'?'0px':css.minWidth);node.setAttribute('data-hn-touch-layout','');}nodes.add(node);resize.observe(node);}
      const minSize=`${minPixels/scale}px`;
      if(node.style.getPropertyValue('--hn-control-hit-min')!==minSize)node.style.setProperty('--hn-control-hit-min',minSize);
      const r=node.getBoundingClientRect();if(!r.width||!r.height){clearHit(node);continue;}
      const boundary=node.closest('dialog')||node.closest('[data-hn-touch-scroll]')||screen,b=boundary.getBoundingClientRect();
      const left=Math.max(shell.left,b.left),right=Math.min(shell.right,b.right),top=Math.max(shell.top,b.top),bottom=Math.min(shell.bottom,b.bottom);
      // Off-screen controls retain their layout size. Removing it here would
      // shrink rows into view, grow them out again, and make scrolling jitter.
      if(right<=left||bottom<=top||r.bottom<=top||r.top>=bottom){clearHit(node);continue;}
      const width=Math.min(right-left,Math.max(r.width,minPixels)),height=Math.min(bottom-top,Math.max(r.height,minPixels));
      const x=Math.max(left,Math.min(right-width,r.left+(r.width-width)/2)),y=Math.max(top,Math.min(bottom-height,r.top+(r.height-height)/2));
      const values=[(x-r.left)/scale,(y-r.top)/scale,width/scale,height/scale];
      props.forEach((key,i)=>node.style.setProperty(key,`${values[i]}px`));node.setAttribute('data-hn-hit-ready','');
    }
  }
  function schedule(){if(!disposed&&!frame)frame=requestAnimationFrame(refresh);}
  const resize=new ResizeObserver(schedule);resize.observe(screen);
  // A transform changes the displayed target size without resizing its CSS box.
  // Ignore our own custom-property writes to avoid a MutationObserver loop.
  let transform=screen.style.transform;
  const transformObserver=new MutationObserver(()=>{const next=screen.style.transform;if(next!==transform){transform=next;schedule();}});
  transformObserver.observe(screen,{attributes:true,attributeFilter:['style']});
  const mutation=new MutationObserver(schedule);mutation.observe(screen,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['class','hidden']});
  screen.addEventListener('scroll',schedule,true);window.addEventListener('resize',schedule);window.visualViewport?.addEventListener('resize',schedule);
  schedule();
  return {refresh:schedule,clear(){cancelAnimationFrame(frame);frame=0;for(const node of nodes)release(node);if(layout)screen.style.removeProperty('--hn-priority-hit-min');},dispose(){disposed=true;cancelAnimationFrame(frame);resize.disconnect();transformObserver.disconnect();mutation.disconnect();screen.removeEventListener('scroll',schedule,true);window.removeEventListener('resize',schedule);window.visualViewport?.removeEventListener('resize',schedule);for(const node of nodes)release(node);if(layout)screen.style.removeProperty('--hn-priority-hit-min');}};
}

