const esc=v=>String(v??'Chưa xác minh').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function waitingWebResult({kind='inbound',state}){
 if(!state?.recorded||state.outcome!=='recorded'||state.unknown)return '';
