function isHistoryFixtureDocument(doc) {
  return (
    doc &&
    typeof doc.id === "string" && doc.id.length > 0 &&
    typeof doc.at === "string" &&
    Array.isArray(doc.lines) && doc.lines.length > 0 &&
    doc.lines.every((line) =>
      line && [line.code, line.sku, line.name].every((value) => typeof value === "string") &&
      ["ITEM", "BOX"].includes(line.kind) &&
      Number.isInteger(line.quantity) && line.quantity > 0
    )
