function newState(scene) {
  const short = [
    "scan",
    "quantity",
    "quantity-invalid",
    "scan-error",
    "resume",
    "drafts",
  ].includes(scene);
  return {
    scene,
    draft: short ? fullDraft().slice(0, 1) : fullDraft(),
    documentId: ["drafts", "resume", "reconcile", "post-check"].includes(scene)
      ? "XLK-0002"
      : undefined,
    recordedCodes: ["resume", "drafts"].includes(scene) ? ["LK0001-HN001"] : [],
    postPhase:
      scene === "success"
        ? "CONFIRMED"
        : scene === "post-check"
        ? "SENT"
        : "NOT_STARTED",
    scanCheckpoint: scene === "reconcile" ? "UNKNOWN" : "VERIFIED",
    historyDocs: [structuredClone(HISTORY_FIXTURES[0])],
    hasMore: true,
    filter: "Tất cả",
    eventId: scene === 'nfc-detail' ? (params.get('event') || 'NFC-E003') : 'NFC-E003',
    caseId: "BH-001",
    sessionId: ['session-detail','sessions'].includes(scene) ? (params.get('session') || 'PQ-0003') : 'PQ-0003',
  };
}
function persist(state) {
  if (mode === "board") return;
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        schema: 1,
        draft: state.draft,
        documentId: state.documentId,
        recordedCodes: state.recordedCodes,
        postPhase: state.postPhase,
        scanCheckpoint: state.scanCheckpoint,
        warehouseId: "KHO-HN",
        version: 3,
      })
    );
  } catch {}
}
function readSaved() {
  try {
    const value = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return value?.schema === 1 && Array.isArray(value.draft) ? value : null;
  } catch {
    return null;
  }
}
function renderPhone(node, state) {
  // Any navigation/rerender invalidates the old page read, even if the user
  // returns to the same scene before it completes.
  const pendingHistory = historyRequests.get(node);
  if (pendingHistory) {
    historyRequests.delete(node);
    pendingHistory.state.loading = false;
  }
  sceneStates.set(node, state);
  node.dataset.scene = state.scene;
  const views = {
    scan: scanView,
    quantity: scanView,
    "quantity-invalid": scanView,
    review: reviewView,
    success: successView,
    history: historyView,
    "history-loading": historyView,
    "history-error": historyView,
    empty: historyView,
    closed: historyView,
    drafts: draftsView,
    resume: resumeView,
    reconcile: reconcileView,
    "post-check": postCheckView,
    "history-hub": historyHub,
    nfc: nfcView,
    "nfc-detail": nfcDetail,
    "events-unavailable": unavailable,
    warranty: warrantyView,
    "warranty-detail": warrantyDetail,
    sessions: sessionsView,
    "session-detail": sessionDetail,
    "scan-error": scanError,
    "waiting-web": waitingWeb,
    documents: documentsView,
  };
  node.innerHTML = (views[state.scene] || scanView)(state);
  const embeddedHistory=params.get('embed')==='history'&&['history-hub','nfc','nfc-detail','events-unavailable','sessions','session-detail'].includes(state.scene);
  node.dataset.historyEmbedded=String(embeddedHistory);
  node.dataset.historyHub=String(embeddedHistory&&state.scene==='history-hub');
  if(embeddedHistory){
    node.querySelector('.history-intro h2 br')?.replaceWith(document.createTextNode(' '));
    if(state.scene==='history-hub'){
      // r03: user removed the hub notice; notification design is deferred.
      // This removes presentation only, never the underlying draft/session.
      node.querySelector('.resume-shortcut')?.remove();
      node.querySelectorAll('.history-link').forEach(button=>{
        button.type='button';
        button.querySelector(':scope > .icon')?.remove();
        button.insertAdjacentHTML('beforeend',icon('chevron','history-forward'));
      });
    }
    const back=node.querySelector('.phone-header [data-action="exit"]');
    if(back)back.setAttribute('aria-label','Về Trang chủ');
  }
  if (["quantity", "quantity-invalid"].includes(state.scene)) {
    node
      .querySelectorAll(":scope > header,:scope > .body,:scope > footer")
      .forEach((el) => (el.inert = true));
    node.insertAdjacentHTML(
      "beforeend",
      quantitySheet(state.scene === "quantity-invalid")
    );
  }
}
function go(node, scene) {
  const state = sceneStates.get(node);
  state.scene = scene;
  renderPhone(node, state);
  if (mode !== "board") {
    selected = scene;
    document
      .querySelectorAll(".scene-nav button")
      .forEach((b) => b.classList.toggle("active", b.dataset.scene === scene));
    history.replaceState(
      null,
      "",
      `?${mode === "screen" ? "mode=screen&" : ""}scene=${scene}`
    );
  }
  if (["quantity", "quantity-invalid"].includes(scene))
    node.querySelector(".sheet")?.focus({ preventScroll: true });
}
function notice(node, text) {
