.p20-customer{display:grid;grid-template-columns:100px minmax(0,1fr);align-items:start;gap:14px;padding-top:14px;margin-top:14px;border-top:1px solid #dce9ef;font-size:15px}.p20-customer>span{color:#527186}.p20-customer strong{text-align:right}
.p20-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.p20-heading h2{min-width:0}.p20-heading .p19-badge{background:#e1f5ea;color:#168657}
.p20-caption{font-size:14px;color:#527186;margin:8px 0 14px!important}
[data-p20-list]{display:flex;flex-direction:column;gap:12px}
.p20-receipt{background:#f9fbfb;border:1px solid #dce9ef;border-radius:12px;padding:16px;min-width:0}
.p20-receipt header{display:flex;align-items:center;gap:9px}.p20-receipt header>strong{flex:1;min-width:0;font-size:17px}.p20-time{font-size:14px;color:#527186;margin:8px 0 4px!important}
.p20-line{display:grid;grid-template-columns:minmax(0,1fr) 110px;gap:12px;padding:13px 0;border-bottom:1px solid #dce9ef;font-size:15px}.p20-line:last-child{border-bottom:0;padding-bottom:0}.p20-line>div{min-width:0}.p20-line p{font-size:14px;color:#527186;margin-top:4px}.p20-quantity{text-align:right}.p20-quantity strong{font-size:14px}.p20-quantity small{display:block;font-size:12px;color:#527186;margin-top:4px}
.p20-note{font-size:14px;margin-top:16px!important;white-space:pre-line}
