.p20-error{display:flex;align-items:flex-start;gap:10px;padding:14px;margin-top:16px;background:#fff0f0;border-radius:10px;color:#b8323a;font-size:14px;line-height:1.6}.p20-error svg{width:20px;height:20px;flex-shrink:0;margin-top:2px}
