.p20-end{font-size:14px;color:#527186;text-align:center;margin-top:16px!important}
.p20-info{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:56px;text-align:left;font-size:15px!important;color:#12384e}
.p20-footer p{font-size:14px;line-height:1.5;color:#527186}
.p20-app [data-hn-readable]{overflow-wrap:anywhere;white-space:pre-line}.p20-app .hn-read-more{min-height:44px}
