.p20-text-button{min-height:44px;border:0;border-radius:7px;padding:8px 0;background:transparent;color:#0c6286;font-size:14px!important;font-weight:600!important;text-align:left}
.p20-text-button:active{background:#eaf5fa}.p20-receipt-fresh{border-color:#0c6286;box-shadow:0 0 0 1px #0c6286}
.p20-fresh-label,.p20-batch{font-size:13px;font-weight:650;color:#0c6286;margin-bottom:10px!important}
.p20-batch{border-bottom:1px dashed #b6d2df;padding-bottom:8px}
[data-p20-new]{text-align:center}[data-p20-new] button{text-align:center}
[data-p20-pending]{font-size:13px;line-height:1.5;min-width:0}[data-p20-pending]>strong{display:block;color:#12384e;font-size:14px}[data-p20-pending]>span{display:block;color:#527186;margin-top:4px;overflow-wrap:anywhere}
.p20-codes-dialog .app-modal-body p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:16px;line-height:1.65;user-select:text}
.p20-quantity strong,.p20-quantity small{overflow-wrap:anywhere;word-break:normal}
/* M20: request-only progress in existing skeleton slot; no geometry/row motion. */
.p20-skeleton{position:relative}
.p20-loading-spinner{position:absolute;left:calc(50% - 12px);top:calc(50% - 12px);width:24px;height:24px;border:2px solid #bed7e0;border-top-color:#0c6286;border-radius:50%;animation:p20-read-spin .9s linear infinite}
