[data-p20-motion-paused="true"] .p20-loading-spinner{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){.p20-loading-spinner{animation:none}}
.p20-tools{border:1px solid #ccdce5;border-radius:12px;padding:14px;margin:10px 0;font:14px/1.5 Arial,sans-serif}.p20-tools button{margin:4px;padding:8px}.p20-tools label{display:block;margin:12px 0}.p20-tools select{max-width:100%;padding:8px}.p20-tools pre{max-height:220px;overflow:auto;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}
.p20-app [hidden]{display:none!important}
