 if(!Number.isSafeInteger(available)||available<0)return 'Tồn khả dụng chưa hợp lệ. Cần kiểm tra lại.';
 return n>available?`Số lượng cần xuất vượt tồn khả dụng${kind==='BOX'?' của hộp':''} (${available}).`:'';
}
