import {recentTimeLabel} from '../shared/recent-time.mjs';
export function checkpointTime(value,now=Date.now()){
 const date=new Date(value);if(!value||!Number.isFinite(+date))return {label:'Chưa xác minh',full:'Chưa xác minh',iso:null};
 const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date).map(p=>[p.type,p.value]));
 return {label:recentTimeLabel(`${parts.year}-${parts.month}-${parts.day}`,`${parts.hour}:${parts.minute}`,now),full:new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',dateStyle:'full',timeStyle:'short'}).format(date),iso:date.toISOString()};
}
export function reconciliationSummary(s){
 const field=v=>v==null||v===''?'Chưa xác minh':String(v);
 return [['Phiếu',s.document?.documentId],['Hồ sơ',s.caseId],['Yêu cầu',s.request?.id],['Phiên quét',s.scanSessionId],['Version',s.document?.version],['Checkpoint',s.checkpoint?.checkpointId]].map(([k,v])=>`${k}: ${field(v)}`).join('\n')+'\nMã:\n'+(s.lines||[]).map(l=>field(l.code)).join('\n');
}
export function resumeReadiness(s,writeError=''){
 if(s.receipt)return 'Phiếu đã xuất · chỉ xem lịch sử';
 if(s.busy)return 'Đang chờ xác nhận · không gửi thêm yêu cầu';
 if(s.unknown)return 'Chưa rõ kết quả · kiểm tra trước khi gửi lại';
 if(s.verification==='loading')return 'Đang xác minh phiếu · chưa thể quét';
 if(writeError)return writeError;
 return s.verification==='verified'?'Có thể tiếp tục quét':'Chưa xác minh dữ liệu phiếu';
}
// Display only: absence is not zero; retain the source value for full reading.
export function resumeCount(value){
 return value==null||String(value).trim()===''||typeof value==='number'&&(!Number.isSafeInteger(value)||value<0)?'Chưa xác minh':String(value);
}

import {createIssueFlow} from './issue-model.mjs';
import {scopeGuard} from '../attachments/model.mjs';
import {caseDetails} from '../warranty/warranty-model.mjs';

const clone=v=>structuredClone(v);
// An independent, page-memory fixture source. This is NOT a server API or durable save.
export function createCheckpointFixture({delay=220}={}){
 const records=new Map();let mode='ready',reads=0;
 return {setMode:v=>{mode=v;},getMode:()=>mode,metrics:()=>({reads}),
  save(record){records.set(record.document.documentId,clone(record));},
  async read(id){reads++;const selected=mode,record=clone(records.get(id));
   if(selected==='hanging')return new Promise(()=>{});
   await new Promise(r=>setTimeout(r,delay));
   if(selected==='error')throw Error('Nguồn đọc chưa khả dụng.');
   if(!record)return {kind:'missing'};
   if(selected==='conflict')record.document.version++;
   return {kind:selected==='unknown'?'unknown':'verified',record};
  },
 };
}
function reference(s){return {document:clone(s.document),scope:clone(s.scope),caseId:s.caseId,scanSessionId:s.scanSessionId,lines:clone(s.lines),request:clone(s.request),unknown:s.unknown,receipt:clone(s.receipt)};}
// Wrap the P19 owner, never reconstruct a new flow when opening a draft.
export function createRetainedIssue({source=createCheckpointFixture(),readTimeout=15000,now=()=>new Date().toISOString(),...options}){
 let block='',verification='unverified',readIssue=null,epoch=0,timer=null,cancelRead=null,checkpoint=null,signature='',disposed=false;
 const flow=createIssueFlow({...options,extraWriteGuard:()=>block});
