/* B21 hierarchy adapted to the user-locked 494×950 shared shell. */
#home-app .hn-screen.p21-screen{height:950px;min-height:950px;overflow:hidden;background:#f3f9fb}
#home-app .p21-screen>.hn-nav{display:none}
#home-app .hn-component-resume{display:flex;flex:1;min-height:0;min-width:0;overflow:hidden}
.p21-app h2{font-size:20px;line-height:1.4;font-weight:650}
.p21-row{display:flex;align-items:center;justify-content:space-between;gap:14px;min-width:0}
.p21-row>strong,.p21-row>span{min-width:0;overflow-wrap:anywhere}
.p21-amber{display:inline-block;border-radius:5px;padding:4px 8px;color:#94600d;background:#fff5e3;font-size:12px;white-space:nowrap;flex-shrink:0}
.p21-muted{font-size:15px;color:#527186;line-height:1.6}
.p21-gap{margin-top:12px!important}
.p21-draft{display:flex;flex-direction:column;gap:16px;font-size:15px}
.p21-draft>p{color:#527186}
.p21-draft .p21-row>strong{font-size:18px}
.p21-draft .p21-muted{font-size:13px}
.p21-open{min-height:44px;padding:6px 10px;flex-shrink:0;background:transparent;border:0;color:#0c6286;font-size:14px!important;border-radius:8px}
.p21-secondary{min-height:58px;padding:12px 16px;border:1px solid #dce9ef;border-radius:12px;background:white;color:#0c6286;font-size:16px!important;font-weight:650!important}
.p21-checkpoint{display:flex;flex-direction:column;gap:12px;color:#527186;font-size:14px;padding:8px 12px}
.p21-checkpoint p{display:flex;gap:12px;align-items:center}
.p21-checkpoint svg{width:19px;height:19px}
.p21-checkpoint.verified svg{color:#168657}
.p21-hero{text-align:center;padding:32px 10px 16px;display:flex;flex-direction:column;align-items:center;gap:22px}
.p21-state-icon{display:grid;place-items:center;width:96px;height:96px;border-radius:28px;background:#eaf5fa;color:#0c6286;margin-bottom:8px}
.p21-state-icon svg{width:38px;height:38px}
.p21-state-icon.warning,.p21-warning{background:#fff5e3;color:#94600d}
.p21-hero h2{font-size:25px;line-height:1.4}
.p21-hero p{font-size:16px;color:#527186;line-height:1.65}
.p21-app .p19-result-summary dt{flex:0 0 36%}
.p21-app .p19-result-summary dd{flex:1;min-width:0}
.p21-app .p19-part-meta{gap:12px}
.p21-app .p19-part-meta>strong{overflow-wrap:anywhere}
.p21-app .p19-context>div{min-width:0}
.p21-app .p19-context>span:last-child{flex-shrink:0}
.p21-app .p19-card{overflow-wrap:anywhere}
.p21-app .p19-footer .p19-link{padding:0}
.p21-app[data-panel="P21.S02"] .p21-scroll{gap:12px}
.p21-app[data-panel="P21.S02"] .p19-card{padding:16px}
.p21-app[data-panel="P21.S02"] .p21-checkpoint{gap:8px;padding:4px 12px}
.p21-tools{border:1px solid #ccdce5;border-radius:12px;padding:14px;margin:10px 0;font:14px/1.5 Arial,sans-serif}.p21-tools button{margin:4px;padding:8px}.p21-tools label{display:block;margin:12px 0}.p21-tools select{max-width:100%;padding:8px}.p21-tools pre{max-height:220px;overflow:auto;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}
/* r02: approved whole-card action, grouped context and footer readiness. */
.p21-draft-wrap{position:relative;border-radius:12px}
.p21-draft-wrap>.p21-draft{width:100%;text-align:left;color:inherit;transition:background-color var(--hn-motion-press,100ms) var(--hn-motion-ease-standard,ease);gap:12px}
.p21-draft-wrap>.p21-draft:hover{background:#f0f7fa}
.p21-draft-wrap>.p21-draft:active{background:#e4f0f5}
.p21-draft-wrap>.hn-read-more{margin-left:18px!important}
.p21-resumed{border-left:3px solid #0c6286}
.p21-resumed-label{padding:6px 16px;background:#eaf5fa;color:#0c6286;font-size:13px;font-weight:600;border-radius:10px 10px 0 0}
.p21-context{display:flex;flex-direction:column;gap:12px}
.p21-case{display:flex;align-items:center;gap:12px;border-top:1px solid #dce9ef;padding-top:12px}
.p21-case>div{min-width:0;flex:1}.p21-case>span:last-child{flex-shrink:0}.p21-case p{font-size:15px;color:#527186}
.p21-ready-summary{font-size:14px;line-height:1.45}.p21-ready-summary strong{font-size:16px}.p21-ready-summary p{color:#527186;margin-top:4px}
.p21-app[data-panel="P21.S02"] .p21-scroll{gap:10px}
.p21-app[data-panel="P21.S02"] .p21-footer{gap:10px;padding-top:12px}
.p21-app[data-panel="P21.S02"] .p21-checkpoint{font-size:13px;gap:4px}
.p21-app[data-panel="P21.S02"] .p19-hint{padding:10px 14px}
.p21-app time{overflow-wrap:anywhere}
/* r03: preserve fixed footer geometry for long source counts; a pending export
   is neutral even when the checkpoint itself has been verified. */
.p21-ready-summary{min-width:0;overflow-wrap:anywhere}
.p21-checkpoint.verified p:last-child svg{color:#527186}
.p21-app .p19-badge{overflow-wrap:anywhere;white-space:normal}
#home-app .p21-identity-dialog .app-modal-body p{white-space:pre-wrap;overflow-wrap:anywhere}

/* M21: replaces the existing hero glyph only while the explicit status read runs. */
.p21-status-spinner{display:inline-flex;width:38px;height:38px;animation:p21-status-spin .9s linear infinite}
@keyframes p21-status-spin{to{transform:rotate(360deg)}}
[data-hn-motion-mode="reduced"] .p21-status-spinner,[data-hn-motion-mode="off"] .p21-status-spinner{animation:none}
[data-p21-motion-paused="true"] .p21-status-spinner{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){.p21-status-spinner{animation:none}.p21-draft-wrap>.p21-draft{transition:none}}

