}
:root {
  --primary: #0c6286;
  --dark: #0c5d7d;
  --support: #5e93a7;
  --near: #fafcfc;
  --ink: #12384e;
  --muted: #527186;
  --line: #dce9ef;
  --canvas: #f3f8fb;
  --soft: #eaf5fa;
  --green: #168657;
  --green-soft: #e1f5ea;
  --red: #c63c43;
  --red-soft: #fff0f0;
  --amber: #a4640c;
  --amber-soft: #fff5e3;
  --header: linear-gradient(110deg, #073b52, #0c5d7d);
  font-family: "Public Sans", Arial, sans-serif;
  color: var(--ink);
  background: var(--near);
  font-synthesis: none;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
select {
  font: inherit;
}
button,
a,
input,
select {
  touch-action: manipulation;
}
button {
  cursor: pointer;
}
a {
  color: var(--primary);
}
button:disabled {
  cursor: default;
  opacity: 0.48;
}
button:focus-visible,
a:focus-visible {
  outline: 3px solid var(--support);
  outline-offset: 3px;
}
button,
input,
select {
  font-variant-numeric: tabular-nums;
}
h1,
h2,
h3,
p {
  margin: 0;
}
.icon {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: none;
}
.icon.small {
  width: 16px;
  height: 16px;
}
.icon.large {
  width: 28px;
  height: 28px;
}
.workbench {
  max-width: 1220px;
  margin: auto;
  display: grid;
  grid-template-columns: minmax(250px, 350px) minmax(360px, 1fr);
  gap: 70px;
  padding: 40px 32px;
  align-items: start;
}
.guide {
  position: sticky;
  top: 36px;
}
.back-library {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 32px;
}
.eyebrow {
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--primary);
  font-weight: 750;
}
.guide h1 {
  font-size: 32px;
  line-height: 1.2;
  letter-spacing: -1px;
  margin: 12px 0;
}
.guide .intro {
  font-size: 14px;
  color: var(--muted);
  line-height: 1.6;
}
.scene-nav {
  display: grid;
  gap: 6px;
  margin: 26px 0;
}
.scene-nav button {
  border: 1px solid transparent;
  background: transparent;
  text-align: left;
  min-height: 46px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--muted);
  border-radius: 10px;
  font-size: 13px;
}
.scene-nav .number {
  font-size: 11px;
  font-weight: 700;
  color: var(--support);
}
.scene-nav button.active {
  background: var(--soft);
  color: var(--dark);
  border-color: var(--line);
  font-weight: 700;
}
.guide-note {
  font-size: 12px;
  color: var(--muted);
  line-height: 1.65;
  border-top: 1px solid var(--line);
  padding-top: 18px;
}
.guide-tools {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 18px;
}
.guide-tools a,
.guide-tools button {
  border: 1px solid var(--line);
  background: white;
  border-radius: 8px;
  padding: 10px 12px;
  color: var(--primary);
  font-size: 12px;
  text-decoration: none;
}
.stage {
  display: flex;
  justify-content: center;
  padding: 10px 0 24px;
}
.phone {
  position: relative;
  isolation: isolate;
  width: 390px;
  height: 844px;
  flex: none;
  overflow: hidden;
  background: var(--canvas);
  border-radius: 26px;
  box-shadow: 0 18px 55px #0c5d7d17, 0 0 0 1px #cddfe6;
  display: flex;
  flex-direction: column;
  font-size: 14px;
  line-height: 1.45;
}
.phone-header {
  flex: none;
  background: var(--header);
  color: white;
  padding: 12px 14px 18px;
}
.statusbar {
  height: 27px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 9px 9px;
  font-size: 12px;
  font-weight: 600;
}
.device {
  display: flex;
  align-items: center;
  gap: 5px;
}
.device .icon {
  width: 16px;
  height: 16px;
}
.battery {
  width: 21px;
  height: 10px;
  border: 1px solid #ffffffaa;
  border-radius: 2px;
  position: relative;
  margin-right: 3px;
}
.battery:before {
  content: "";
  position: absolute;
  inset: 1px;
  background: white;
  border-radius: 1px;
}
.battery:after {
  content: "";
  position: absolute;
  right: -3px;
  top: 2px;
  width: 2px;
  height: 4px;
  background: #ffffffaa;
  border-radius: 1px;
}
.titlebar {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) 40px;
  align-items: center;
  gap: 5px;
  min-height: 44px;
}
.titlebar h1 {
  text-align: center;
  font-size: 17px;
  font-weight: 650;
  letter-spacing: -0.45px;
  white-space: nowrap;
}
.icon-button {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  color: inherit;
  border-radius: 10px;
  padding: 0;
}
.body {
  overflow-y: auto;
  overflow-x: hidden;
  flex: 1;
  min-height: 0;
  padding: 18px 16px 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  scrollbar-width: none;
  background: linear-gradient(150deg, #f4fafd, var(--near));
  border-radius: 20px 20px 0 0;
  margin-top: -9px;
}
.body::-webkit-scrollbar {
  display: none;
}
.card {
  padding: 15px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  box-shadow: 0 3px 10px #124b6504;
}
.row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.between {
  justify-content: space-between;
}
.grow {
  flex: 1;
  min-width: 0;
}
.muted {
  color: var(--muted);
}
.tiny {
  font-size: 11px;
}
.small-copy {
  font-size: 12px;
  line-height: 1.5;
}
.section-title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.35px;
}
.icon-tile {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  flex: none;
  background: var(--soft);
  color: var(--primary);
}
.icon-tile.warm {
  background: var(--amber-soft);
  color: var(--amber);
}
.label {
  display: block;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 3px;
}
.case-id {
  font-size: 16px;
  font-weight: 750;
  letter-spacing: -0.3px;
}
.badge {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
  border-radius: 6px;
  padding: 5px 7px;
  color: var(--primary);
  background: var(--soft);
}
.badge.green {
  color: var(--green);
  background: var(--green-soft);
}
.badge.amber {
  color: var(--amber);
  background: var(--amber-soft);
}
.case-context .model {
  font-size: 12px;
  color: var(--muted);
  margin-top: 3px;
}
.steps {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: space-between;
  padding: 0 2px;
}
.step {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--muted);
  white-space: nowrap;
}
.step i {
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-style: normal;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: white;
}
.step.active {
  color: var(--primary);
  font-weight: 650;
}
.step.active i {
  background: var(--primary);
  color: white;
  border-color: var(--primary);
}
.step.past i {
  background: var(--green-soft);
  color: var(--green);
  border-color: var(--green-soft);
}
.step-line {
  height: 1px;
  background: var(--line);
  flex: 1;
}
.scan-heading {
  display: flex;
  align-items: center;
  gap: 11px;
}
.scan-heading h2 {
  font-size: 15px;
  letter-spacing: -0.3px;
}
.camera {
  height: 238px;
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: #073b52;
  flex: none;
}
.camera img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}
.camera:after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #00172725, #00172766);
}
.camera-corners {
  position: absolute;
  z-index: 1;
  inset: 30px 44px;
}
.camera-corners i {
  position: absolute;
  width: 27px;
  height: 27px;
  border: 3px solid #d2f3ff;
  border-radius: 3px;
}
.camera-corners i:nth-child(1) {
  left: 0;
  top: 0;
  border-right: 0;
  border-bottom: 0;
}
.camera-corners i:nth-child(2) {
  right: 0;
  top: 0;
  border-left: 0;
  border-bottom: 0;
}
.camera-corners i:nth-child(3) {
  left: 0;
  bottom: 0;
  border-right: 0;
  border-top: 0;
}
.camera-corners i:nth-child(4) {
  right: 0;
  bottom: 0;
  border-left: 0;
  border-top: 0;
}
.scan-line {
  position: absolute;
  z-index: 2;
  left: 47px;
  right: 47px;
  top: 50%;
  height: 2px;
  background: #e6f8ff;
  box-shadow: 0 0 10px #b1eaff;
  animation: scan 2.6s ease-in-out infinite;
}
.camera-prompt {
  position: absolute;
  z-index: 2;
  left: 15px;
  right: 15px;
  bottom: 11px;
  text-align: center;
  font-size: 10px;
  color: white;
  background: #073b52b8;
  padding: 5px;
  border-radius: 6px;
}
.scan-tools {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.soft-button {
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #fff;
  color: var(--primary);
  font-size: 12px;
  font-weight: 650;
}
.scan-count {
  padding: 13px 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.count-value {
  font-size: 26px;
  color: var(--primary);
  font-weight: 750;
  line-height: 1.1;
}
.count-value span {
  font-size: 12px;
  color: var(--muted);
  font-weight: 450;
  margin-left: 7px;
}
.inline-success {
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
}
.scan-record {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-top: 9px;
}
.scan-record strong {
  font-size: 12px;
  font-weight: 650;
}
.scan-record .icon {
  color: var(--green);
}
.hint {
  background: var(--soft);
  border-radius: 10px;
  padding: 11px 12px;
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--primary);
}
.hint .icon {
  width: 17px;
  height: 17px;
  margin-top: 1px;
}
.hint.danger {
  background: var(--red-soft);
  color: var(--red);
}
.hint.warning {
  background: var(--amber-soft);
  color: var(--amber);
}
.phone-footer {
  flex: none;
  background: #fff;
  border-top: 1px solid var(--line);
  padding: 12px 16px 4px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.primary,
.secondary {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 48px;
  width: 100%;
  border-radius: 9px;
  font-size: 13px;
