// User-authorized intake symptom choices. UI keys only, not backend status enums.
export const FAULT_OPTIONS=Object.freeze([
 ['power-off','Máy không lên nguồn'],
 ['power-unstable','Nguồn chập chờn / Tự tắt máy'],
 ['no-print','Không in được'],
 ['faint-print','Bản in mờ / Không rõ nét'],
 ['broken-print','Bản in bị sọc / Đứt nét'],
 ['label-offset','In lệch tem / Sai vị trí'],
 ['paper-jam','Kẹt giấy / Kẹt tem'],
 ['paper-sensor','Không nhận giấy / Tem'],
 ['cutter','Không cắt giấy / Lỗi dao cắt'],
 ['no-scan','Không quét được mã vạch'],
 ['unstable-scan','Quét mã chậm / Chập chờn'],
 ['usb','Không kết nối USB'],
 ['lan','Không kết nối mạng LAN'],
 ['bluetooth','Không kết nối Bluetooth'],
 ['wifi','Không kết nối Wi-Fi'],
 ['button','Nút bấm không hoạt động'],
 ['physical','Hư vỏ máy / Cổng kết nối'],
 ['other','Khác'],
].map(([id,name])=>Object.freeze({id,name})));
export const faultOption=id=>FAULT_OPTIONS.find(o=>o.id===id)||null;
export const faultText=d=>d.faultId==='other'?String(d.faultOther??'').trim():faultOption(d.faultId)?.name||'';
export function faultError(d){
 if(!faultOption(d.faultId))return 'Vui lòng chọn lỗi tiếp nhận.';
 if(d.faultId==='other'&&!String(d.faultOther??'').trim())return 'Mô tả tình trạng khi chọn “Khác”.';
 if(d.faultId==='other'&&String(d.faultOther??'').length>200)return 'Mô tả tình trạng tối đa 200 ký tự.';
 return '';
}

// P09-only browser-history boundary. UI Back dismisses a dialog before a page.
export function createWarrantyModalHistory({history,location}){
 let open=null,closing=null,resolveClose=null,settlement=Promise.resolve();
 function begin(){
  const token=crypto.randomUUID();
  open={token,hash:location.hash,state:structuredClone(history.state||{})};
  history.pushState({...open.state,p09Modal:token},'',open.hash);
 }
 function closed(){
  const entry=open;open=null;
  if(entry&&history.state?.p09Modal===entry.token){
   closing=entry;settlement=new Promise(resolve=>resolveClose=resolve);history.back();
  }
 }
 function onNavigation(close){
  if(open&&history.state?.p09Modal!==open.token){const same=location.hash===open.hash;close();return same;}
  if(closing){const same=location.hash===closing.hash;closing=null;resolveClose?.();resolveClose=null;return same;}
  return false;
 }
 return {begin,closed,onNavigation,ready:()=>settlement,
  stripStale(){if(!open&&history.state?.p09Modal){const state={...history.state};delete state.p09Modal;history.replaceState(state,'',location.hash);return true;}return false;},
  dispose(){open=null;closing=null;resolveClose?.();resolveClose=null;settlement=Promise.resolve();},
 };
}

import {createMotionController} from '../shared/motion/motion-primitives.mjs';

// M09 descendant feedback only; shell/overlay/domain/native scroll keep ownership.
export function mountWarrantyMotion({root,requested='auto',active=()=>true,media}){
 let controller=null,disposed=false;const errors=new Map(),receipts=new Set();
 const mark=(n,name)=>{if(n)n.dataset.motionPrimitive=name;return n;};
 const usable=()=>!disposed&&active()&&!root.closest('[inert]');
 function press(e){
  if(e.type==='keydown'&&(e.repeat||e.isComposing||!['Enter',' '].includes(e.key)))return;
  const n=e.target.closest?.('.p09-case,[data-p09-status],#p09-fault-select');
  if(!controller||!usable()||!n||!root.contains(n)||n.disabled||n.closest('[inert],dialog'))return;
  controller.pressFeedback(mark(n,'WarrantyPress'));
 }
 root.addEventListener('pointerdown',press);root.addEventListener('keydown',press);
 return {
  activate(){if(!disposed&&!controller)controller=createMotionController({element:root,requested,...(media?{media}:{})});},
  setMode(v){requested=v;controller?.setMode(v);},
  filter(n){controller?.cancel();if(usable())controller?.dataState(mark(n,'WarrantyFilter'));},
  tab(n){if(usable())controller?.noticeFeedback(mark(n,'CaseTabs'));},
  validation(n,key,message){const prior=errors.get(key)||'';errors.set(key,message);if(prior===message)return;if(!message){controller?.cancel();return;}if(usable())controller?.noticeFeedback(mark(n,'WarrantyFormFeedback'));},
  success(n,id){if(!id||receipts.has(id))return;receipts.add(id);if(usable())controller?.rowFeedback(mark(n,'WarrantySuccess'));},
  cancel(){controller?.cancel();},
  hide(){controller?.dispose();controller=null;},
  dispose(){disposed=true;controller?.dispose();controller=null;errors.clear();receipts.clear();root.removeEventListener('pointerdown',press);root.removeEventListener('keydown',press);},
 };
}

