const fold=s=>s.normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/đ/gi,'d').toLowerCase();
export function mountWarranty({root,tools,screen,getState,onHome,onSize,onLookup,onHandoff,onIssue,onComponentHistory,getPendingIssue=()=>null,getIssuedDocuments=()=>[],motionMode='auto'}){
 const postedDocuments=id=>[...baselinePosted(id),...getIssuedDocuments().filter(r=>r.caseId===id&&r.status==='POSTED')];
 const componentSummary=id=>{const documents=postedDocuments(id),known=baselineSummary(id).known||documents.length>0;return {documents,known,quantity:known?documents.flatMap(d=>d.lines).reduce((n,l)=>n+l.quantity,0):null};};
 let active=false,disposed=false,panel=1,caseId=null,tab='info',query='',status='all',sort='desc',message='',modal=null,listTop=0,listFocus=null;
 let kpiMode=false,normalList={query:'',status:'all',sort:'desc'};
 function saveListFilters(){if(panel!==1)return;const saved={query,status,sort};if(kpiMode)history.replaceState({...history.state,p09KpiFilters:saved},'',location.hash);else normalList=saved;}
 function enterListFilter(q){if(panel!==1)return;const nextKpi=q.get('kpi')==='open';if(nextKpi){const saved=history.state?.p09KpiFilters||{query:'',status:'open',sort:'desc'};({query,status,sort}=saved);if(!history.state?.p09KpiFilters){listTop=0;listFocus=null;returnedCaseId=null;}}else if(kpiMode){({query,status,sort}=normalList);listTop=0;listFocus=null;}kpiMode=nextKpi;}
 const flow=createWarrantyFlow(getState),positions=new Map();
