 const review=document.createElement('section');review.className='p09-tools';review.hidden=true;
 review.innerHTML='<details><summary>P09 · Kiểm thử prototype</summary><p>Fixture bộ nhớ, không kết nối WMS/camera. Policy 200 ký tự theo ảnh B09, chưa phải backend policy.</p><label>Kết quả adapter <select data-p09-mode><option value="ready">Xác nhận</option><option value="error">Lỗi</option><option value="unknown">UNKNOWN cần đối chiếu</option></select></label><button data-p09-read>Đọc serial fixture HN12345</button><p>Serial mới có khách hàng mẫu: SN-XP420B-BK-0008.</p><pre data-p09-snapshot></pre></details>';tools.append(review);
 function remember(){if(!active)return;const scroll=root.querySelector('.p09-scroll');if(scroll)positions.set(panel+':'+caseId+':'+tab,scroll.scrollTop);if(panel===1){listTop=scroll?.scrollTop||0;listFocus=document.activeElement?.dataset.p09Case||listFocus;}}
 function nav(p,id=caseId,{replace=false,nextTab=tab}={}){
  remember();const from=location.hash,prior=history.state||{};panel=p;caseId=id;tab=nextTab;message='';
  const q=new URLSearchParams({panel:p});if(id)q.set('case',id);if(p===3)q.set('tab',tab);
  history[replace?'replaceState':'pushState'](replace?{...prior,p09:true}:{p09:true,p09From:from,...(prior.p09Journey?.owner===journeyOwner?{p09Journey:{...prior.p09Journey,depth:prior.p09Journey.depth+1}}:{})},'',`#p02/warranty?${q}`);
  renderedHash=location.hash;render(true);
 }
 function markJourney(){if(history.state?.p09Journey?.owner!==journeyOwner)history.replaceState({...history.state,p09Journey:{owner:journeyOwner,id:crypto.randomUUID(),depth:0}},'',location.hash);}
 function listAtRoot(){pendingListReturn=false;backPending=false;history.replaceState({...history.state,p09:true},'','#p02/warranty?panel=1'+(kpiMode?'&kpi=open':''));show();}
 function returnToList(){
  if(backPending)return;returnedCaseId=caseId;remember();const journey=history.state?.p09Journey;
  if(journey?.owner===journeyOwner&&journey.depth>0){pendingListReturn=true;backPending=true;history.go(-journey.depth);}
