 function hero(c){return `<section class="p09-case-summary"><div class="p09-hero"><img src="${img}" alt="Ảnh minh họa thiết bị"><div><div class="p09-between"><strong>${esc(c.id)}</strong>${badge(c)}</div><b>${esc(c.model)}</b><small>Serial: <span>${esc(c.serial)}</span></small></div></div><div class="p09-dates"><div>${tile('calendar','documents','sm')}<span><small>Ngày tiếp nhận</small><time>${date(c.events[0].day||c.day,c.events[0].time)}</time></span></div><div>${tile('clock','documents','sm')}<span><small>Cập nhật gần nhất</small><time>${date(c.day,c.time)}</time></span></div></div></section>`;}
 function queryCases(){return readWarrantyCases().map(c=>caseDetails(c.id)).filter(c=>fold([c.id,c.serial,c.model,c.customer,c.fault].join(' ')).includes(fold(query.trim())));}
