 function cardHeading(glyph,title,subtitle){return `<div class="p09-card-heading">${tile(glyph,'warranty','sm')}<div><h2>${title}</h2><p>${subtitle}</p></div></div>`;}
 function faultMarkup(){const d=flow.draft,locked=flow.snapshot().busy||flow.snapshot().unknown,selected=faultOption(d.faultId);return `<div class="p09-fault-field"><label id="p09-fault-label">Lỗi tiếp nhận <em>*</em></label><button type="button" id="p09-fault-select" data-p09="fault" class="p09-fault-select ${selected?'':'is-placeholder'}" aria-haspopup="dialog" aria-labelledby="p09-fault-label p09-fault-value" aria-describedby="p09-fault-help p09-fault-error" ${locked?'disabled':''}><span id="p09-fault-value">${esc(selected?.name||'Chọn tình trạng của thiết bị')}</span><span class="p09-fault-change">${selected?'Thay đổi':icon('chevron')}</span></button><p id="p09-fault-help" class="p09-field-help">Chọn một lỗi chính; có thể tìm nhanh theo tên.</p></div>${d.faultId==='other'?`<div class="p09-other-field">${intakeField('faultOther','Mô tả tình trạng khác','Mô tả biểu hiện lỗi hoặc tình trạng thiết bị',{required:true})}</div>`:''}<p id="p09-fault-error" class="p09-field-error" role="status" ${faultTouched&&faultError(d)?'':'hidden'}>${faultTouched?esc(faultError(d)):''}</p>`;}
 function intakeField(name,title,placeholder,{required=false}={}){const d=flow.draft,s=flow.snapshot();return `<label class="p09-field"><span class="p09-field-label"><span>${title}${required?' <em>*</em>':''}</span>${required?'':'<span class="p09-optional">Không bắt buộc</span>'}</span><textarea name="${name}" aria-label="${title}" maxlength="200" ${required?'required aria-describedby="p09-fault-error"':''} placeholder="${placeholder}" ${s.busy||s.unknown?'readonly':''}>${esc(d[name])}</textarea><small data-counter="${name}">${d[name].length}/200</small></label>`;}
