 function parts(c,summary=false){
  const docs=postedDocuments(c.id),row=l=>`<div class="p09-part">${tile('box','documents','sm')}<span class="p09-part-copy"><strong>${esc(l.sku)}</strong><small>${esc(l.name)}</small></span><span class="p09-part-quantity"><small>Số lượng</small><b>${l.quantity}</b></span></div>`;
